import logo from './img.svg';
import QuestionForm from './components/QuestionForm';

function App() {
  return (
    <div className="min-h-screen bg-gray-100 p-6">

      <div className="flex items-center gap-3 mb-6">
        <img
          src={logo}
          alt="Logo"
          className="w-14 h-14"
        />

        <h1 className="text-3xl font-bold">
          Nested Dynamic Form
        </h1>
      </div>

      <QuestionForm />

    </div>
  );
}

export default App;
